-- Fix: allow anon users to read custom_categories (needed for signup form)-- Drop the old authenticated-only read policyDROP POLICY IF EXISTS "Authenticated users can read categories" ON custom_categories;DROP POLICY IF EXISTS "All users can read categories" ON custom_categories;-- Create read policy for all users including anonCREATE POLICY "All users can read categories"  ON custom_categories  FOR SELECT  TO anon, authenticated  USING (true);